<script>
(() => { const r=document.getElementById('hubRegion'),p=document.getElementById('hubProvince'),c=document.getElementById('hubCity'),b=document.getElementById('hubBarangay'),z=document.getElementById('hubPostalCode'); const get=x=>fetch(`/address/${x}`).then(v=>v.ok?v.json():Promise.reject()); const fill=(el,items,label)=>{el.innerHTML=`<option value="">${label}</option>`;items.forEach(x=>el.add(new Option(x.name,x.code)));el.disabled=false}; const reset=(el,label)=>{el.innerHTML=`<option value="">${label}</option>`;el.disabled=true}; get('regions').then(x=>fill(r,x,'Select region'));r.onchange=async()=>{reset(p,'Loading provinces…');reset(c,'Select province or region first');reset(b,'Select city first');z.value='';const x=await get(`regions/${encodeURIComponent(r.value)}/provinces`);if(x.length)fill(p,x,'Select province');else{reset(p,'No province required');fill(c,await get(`regions/${encodeURIComponent(r.value)}/cities-municipalities`),'Select municipality / city')}};p.onchange=async()=>{reset(c,'Loading cities…');reset(b,'Select city first');fill(c,await get(`provinces/${encodeURIComponent(p.value)}/cities-municipalities`),'Select municipality / city')};c.onchange=async()=>{reset(b,'Loading barangays…');z.value='';const [barangays,postal]=await Promise.all([get(`cities-municipalities/${encodeURIComponent(c.value)}/barangays`),get(`cities-municipalities/${encodeURIComponent(c.value)}/postal-code`).catch(()=>({}))]);fill(b,barangays,'Select barangay');z.value=postal.postal_code||''}; })();
</script>
